-- R6 audited contract-handoff selection and operational status history.
CREATE OR REPLACE FUNCTION public.mmhr_record_contract_handoff(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; handoff public.contract_handoffs%ROWTYPE; v_action text; v_org uuid; v_actor uuid; v_id uuid; v_deal uuid; v_vendor uuid; v_from text; v_to text; v_expected integer; v_reasons jsonb; v_risks jsonb; v_approvers jsonb; v_reason text;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','transition') OR correlation_id IS NULL OR idempotency_key IS NULL OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid handoff input'; END IF;
 v_action:=payload->>'action'; v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record contract handoff',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF;
 receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r6.contract.handoff',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('handoffId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF coalesce(payload->>'handoffId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'dealId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'customerOrganizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'vendorOrganizationId','') !~ '^[0-9a-fA-F-]{36}$' OR jsonb_typeof(payload->'selectionReasons')<>'array' OR jsonb_array_length(payload->'selectionReasons') NOT BETWEEN 1 AND 10 OR jsonb_typeof(payload->'remainingRisks')<>'array' OR jsonb_array_length(payload->'remainingRisks')>20 OR jsonb_typeof(payload->'approvedByIdentityIds')<>'array' OR jsonb_array_length(payload->'approvedByIdentityIds') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid handoff create'; END IF;
   v_id:=(payload->>'handoffId')::uuid; v_deal:=(payload->>'dealId')::uuid; v_vendor:=(payload->>'vendorOrganizationId')::uuid; IF (payload->>'customerOrganizationId')::uuid<>v_org OR v_vendor=v_org OR NOT EXISTS(SELECT 1 FROM public.deals d WHERE d.id=v_deal AND d.organization_id=v_org AND d.vendor_organization_id=v_vendor) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Handoff deal scope denied'; END IF;
   INSERT INTO public.contract_handoffs(id,organization_id,deal_id,customer_organization_id,vendor_organization_id,selection_reasons,remaining_risks,approved_by_identity_ids,approved_at,status,revision,correlation_id) VALUES(v_id,v_org,v_deal,v_org,v_vendor,payload->'selectionReasons',payload->'remainingRisks',payload->'approvedByIdentityIds',(payload->>'approvedAt')::timestamptz,'introduction_pending',1,correlation_id) RETURNING * INTO handoff;
 ELSE
   v_id:=(payload->>'handoffId')::uuid; SELECT * INTO handoff FROM public.contract_handoffs WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Handoff association denied'; END IF;
   v_from:=payload->>'fromStatus'; v_to:=payload->>'toStatus'; v_expected:=coalesce((payload->>'expectedRevision')::integer,0); v_reason:=btrim(payload->>'reason');
   IF v_from<>handoff.status OR v_expected<>handoff.revision OR length(v_reason) NOT BETWEEN 1 AND 1000 OR v_to NOT IN ('introduced','negotiating','stalled','signed','not_signed','cancelled') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Handoff transition denied'; END IF;
   IF (handoff.status='introduction_pending' AND v_to NOT IN ('introduced','stalled','cancelled')) OR (handoff.status='introduced' AND v_to NOT IN ('negotiating','stalled','cancelled')) OR (handoff.status='negotiating' AND v_to NOT IN ('signed','not_signed','stalled','cancelled')) OR (handoff.status='stalled' AND v_to NOT IN ('introduced','negotiating','cancelled')) OR handoff.status IN ('signed','not_signed','cancelled') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Handoff transition denied'; END IF;
   UPDATE public.contract_handoffs SET status=v_to,revision=revision+1 WHERE id=v_id AND organization_id=v_org RETURNING * INTO handoff;
   INSERT INTO public.contract_handoff_history(organization_id,handoff_id,from_status,to_status,actor_identity_id,reason,occurred_at,correlation_id) VALUES(v_org,v_id,v_from,v_to,v_actor,v_reason,(payload->>'occurredAt')::timestamptz,correlation_id);
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r6.contract.handoff','handoff.'||v_action,'contract_handoff',handoff.id,v_org,'Record contract handoff',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('handoffId',handoff.id,'organizationId',handoff.organization_id,'status',handoff.status,'revision',handoff.revision,'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_contract_handoff(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_contract_handoff(jsonb,uuid,uuid) TO authenticated;
